package com.example.familymenu.category.service;
import com.example.familymenu.category.domain.*; import com.example.familymenu.category.repository.*; import com.example.familymenu.common.exception.BusinessException; import com.example.familymenu.dish.repository.DishRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class CategoryServiceImpl implements CategoryService {private final CategoryRepository repo;private final DishRepository dishes;public List<DishCategory> list(boolean all){return repo.findAll(all);}public DishCategory create(String n,Integer s,Boolean e){if(repo.findByName(n).isPresent())throw new BusinessException("菜品类型已存在");return repo.save(new DishCategory(null,n,s==null?0:s,e==null||e));}public DishCategory update(Long id,String n,Integer s,Boolean e){DishCategory old=repo.findById(id).orElseThrow(()->new BusinessException("菜品类型不存在: "+id));Optional<DishCategory> same=repo.findByName(n);if(same.isPresent()&&!same.get().getId().equals(id))throw new BusinessException("菜品类型已存在");if(!old.getName().equals(n))dishes.renameCategory(old.getName(),n);return repo.save(new DishCategory(id,n,s==null?old.getSort():s,e==null?old.isEnabled():e));}public void delete(Long id){DishCategory c=repo.findById(id).orElseThrow(()->new BusinessException("菜品类型不存在: "+id));if(dishes.countByCategory(c.getName())>0)throw new BusinessException("该类型下还有菜品，不能删除，请先迁移菜品");if(!repo.deleteById(id))throw new BusinessException("菜品类型不存在: "+id);}}
